<div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">League & Competition</h1><p class="text-muted mb-0">Theo dõi lịch đấu, standings và ladder challenge.</p></div><form method="get" class="d-flex gap-2"><select name="event_id" class="form-select"><?php foreach($events as $item): ?><option value="<?= (int)$item->id ?>" <?= $event&&(int)$event->id===(int)$item->id?'selected':'' ?>><?= esc($item->name) ?></option><?php endforeach; ?></select><button class="btn btn-outline-secondary">Xem</button></form></div><?php if(!$event): ?><div class="alert alert-light">Chưa có competition công khai.</div><?php else: ?><div class="card shadow-sm mb-4"><div class="card-body"><h2 class="h5 mb-1"><?= esc($event->name) ?></h2><span class="badge text-bg-success"><?= esc($event->status) ?></span> <span class="badge text-bg-secondary"><?= esc($event->format) ?></span></div></div><?php if($event->format==='ladder'&&$ladderChallenges): ?><div class="card shadow-sm mb-4"><div class="card-header">Ladder challenge của bạn</div><div class="list-group list-group-flush"><?php foreach($ladderChallenges as $challenge): ?><?php if((int)$challenge->opponent_id===(int)$playerId&&$challenge->status==='requested'): ?><div class="list-group-item d-flex justify-content-between align-items-center"><span><?= esc($challenge->challenger_name) ?> thách đấu bạn · <?= esc($challenge->scheduled_date) ?></span><span><form method="post" action="<?= base_url('player/competitions/ladder/'.$challenge->id.'/respond') ?>" class="d-inline"><?= csrf_field() ?><input type="hidden" name="decision" value="accept"><button class="btn btn-sm btn-success">Chấp nhận</button></form><form method="post" action="<?= base_url('player/competitions/ladder/'.$challenge->id.'/respond') ?>" class="d-inline ms-1"><?= csrf_field() ?><input type="hidden" name="decision" value="reject"><button class="btn btn-sm btn-outline-secondary">Từ chối</button></form></span></div><?php endif; ?><?php endforeach; ?></div></div><?php endif; ?><div class="row g-4"><div class="col-lg-6"><div class="card shadow-sm"><div class="card-header">Bảng xếp hạng</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>#</th><th>VĐV/Team</th><th>Trận</th><th>W–D–L</th><th>Điểm</th></tr></thead><tbody><?php foreach($standings as $row): ?><tr><td><?= (int)$row->rank_no ?></td><td><?= esc($row->display_name) ?></td><td><?= (int)$row->played ?></td><td><?= (int)$row->wins ?>–<?= (int)$row->draws ?>–<?= (int)$row->losses ?></td><td><strong><?= (int)$row->points ?></strong></td></tr><?php endforeach; ?></tbody></table></div></div></div><div class="col-lg-6"><div class="card shadow-sm"><div class="card-header">Lịch thi đấu</div><div class="list-group list-group-flush"><?php foreach($fixtures as $fixture): ?><div class="list-group-item d-flex justify-content-between"><span>V<?= (int)$fixture->round_no ?> · <?= esc($fixture->participant_a_name) ?> – <?= esc($fixture->participant_b_name) ?></span><strong><?= $fixture->status==='completed'?(int)$fixture->score_a.'–'.(int)$fixture->score_b:'Chưa đấu' ?></strong></div><?php endforeach; ?></div></div></div></div><?php endif; ?></div>
<?php if($event&&$myParticipant&&$myParticipant->invoice_id): ?><div class="card shadow-sm mt-4"><div class="card-body d-flex justify-content-between align-items-center"><div><strong>Phí tham dự</strong><div class="small text-muted">Competition entry fee · <?= esc($myParticipant->display_name) ?> · <?= esc($myParticipant->invoice_status??'unpaid') ?></div></div><?php if(($myParticipant->invoice_status??'')!=='paid'): ?><form method="post" action="<?= base_url('player/competitions/participants/'.$myParticipant->id.'/pay') ?>"><?= csrf_field() ?><button class="btn btn-success">Thanh toán bằng ví</button></form><?php endif; ?></div></div><?php endif; ?>
